  [8, line("0 ~ ~ ~ 2 ~ 1 ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ 0 ~ ~ ~ -1 ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ 0 ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~")]
